'use strict';
(()=>{
 const M=FamilyMaintenance,assets=document.querySelector('[data-page="assets"]'),income=document.querySelector('[data-page="income"]');
 function cell(value){const td=document.createElement('td');td.textContent=value??'';return td;}
 function buttons(items){const td=document.createElement('td');td.className='row-actions';for(const [label,fn]of items)td.append(M.button(label,fn));return td;}
 function trashAt(parent,kind){const b=M.button('回收站',()=>M.openTrash(kind));b.classList.add('inline-trash');parent.append(b);}
 function header(tbody){const tr=tbody.closest('table').querySelector('thead tr');if(!tr.querySelector('.operation-header')){const th=document.createElement('th');th.className='operation-header';th.textContent='操作';tr.append(th);}}
 function expenseEdit(month){location.hash='#entry';$('workflowMonth').value=month;$('workflowMonth').dispatchEvent(new Event('change'));window.FamilyMonth?.showView('flows');$('monthlyExpensePanel').scrollIntoView({behavior:'smooth'});}
 const sourceDialog=document.createElement('dialog');sourceDialog.className='maintenance-dialog';const sourceTitle=document.createElement('h2'),sourceRows=document.createElement('div'),sourceClose=M.button('关闭',()=>sourceDialog.close());sourceDialog.append(sourceTitle,sourceRows,sourceClose);document.body.append(sourceDialog);
 function snapshotEdit(date){sourceTitle.textContent=date+' · 修改资产来源记录';sourceRows.replaceChildren();const hist=(D.history||[]).filter(r=>r.kind==='assets'&&r.date===date),records=(D.records||[]).filter(r=>r.date===date&&r.order>0&&!r.portfolioValuation);for(const [kind,r,id]of [...hist.map(r=>['history',r,r.key]),...records.map(r=>['record',r,r.order])]){const row=document.createElement('p');row.textContent=[r.date,D.accounts.find(a=>a.id===r.account)?.name||'家庭总资产',nativeMoney(r.cents,r.currency||'CNY'),r.memo].filter(Boolean).join(' · ');row.append(M.button('修改',()=>{sourceDialog.close();M.edit(kind,id,r);}));sourceRows.append(row);}if(!hist.length&&!records.length)sourceRows.textContent='这是旧持仓估值生成的展示点；可以删除展示点，或在上方账户中更新当前估值。';sourceDialog.showModal();}
 function draw(){if(!D.live)return;for(const b of document.querySelectorAll('.inline-trash'))b.disabled=window.currentFamilyUser?.role!=='admin';sourceClose.disabled=false;
  // Income rows follow the active report; historical aggregates use their original keys.
  const rows=$('incomeRows');header(rows);rows.replaceChildren();for(const r of current?.rows||[]){const history=r.historical,id=history?r.key:r.order;const original=history?(D.history||[]).find(x=>x.key===id):(D.records||[]).find(x=>x.order===id);const tr=document.createElement('tr');for(const text of [history?FamilyHistoryPeriod.label(r):r.date,memberName(r.member),r.source,history?'历史汇总（不关联账户）':D.accounts.find(a=>a.id===r.account)?.name||r.account,money(r.cents)])tr.append(cell(text));if(original)tr.append(buttons([['修改',()=>M.edit(history?'history':'record',id,original)],['删除',()=>M.check({action:history?'delete-history':'delete-record',id})]]));else tr.append(cell('旧持仓记录'));rows.append(tr);}if(!rows.children.length){const tr=document.createElement('tr'),td=cell('所选区间没有收入记录');td.colSpan=6;tr.append(td);rows.append(tr);}
  // Account actions remain beside each account, including archive / unarchive.
  const accountRows=$('unifiedAccountRows');for(const tr of accountRows.children){const a=(D.balances||[]).find(a=>a.id===tr.dataset.accountId);if(!a||a.portfolioLegacy)continue;const td=tr.querySelector('td.row-actions')||tr.lastElementChild;const update=td.querySelector('button');if(update)update.textContent='修改';for(const old of td.querySelectorAll('.inline-account'))old.remove();for(const [text,action]of [[a.archivedAt?'恢复使用':'归档',a.archivedAt?'unarchive-account':'archive-account'],['删除','delete-account']]){const b=M.button(text,()=>M.check({action,id:a.id}));b.classList.add('inline-account');td.append(b);}td.classList.add('row-actions');}
  // Monthly expenses are edited in the existing monthly form, without a second accounting path.
  const er=$('expenseReportRows');header(er);const e=current?.familyExpense;er.replaceChildren();for(const r of e?.rows||[]){const tr=document.createElement('tr');for(const text of [r.month,r.through,money(r.cents),(r.breakdown||[]).map(b=>memberName(b.member)+' '+money(b.cents)).join('；')+(r.memo?' · '+r.memo:'')])tr.append(cell(text));tr.append(buttons([['修改',()=>expenseEdit(r.month)],['删除',()=>M.check({action:'delete-expense',id:r.month})]]));er.append(tr);}if(!er.children.length){const tr=document.createElement('tr'),td=cell('此范围暂无可完整计入的月度支出');td.colSpan=5;tr.append(td);er.append(tr);}
  $('savedExpenseMonths').replaceChildren();for(const r of (D.expenseSummaries||[]).filter(r=>r.scope==='household').slice().sort((a,b)=>b.month.localeCompare(a.month))){const row=document.createElement('div');row.className='maintenance-row';const text=document.createElement('span');text.textContent=r.month+' · '+money(r.cents);row.append(text,M.button('修改',()=>expenseEdit(r.month)),M.button('删除',()=>M.check({action:'delete-expense',id:r.month})));$('savedExpenseMonths').append(row);}
  // Asset history removes the display point, not the underlying account balances.
  const sr=$('snapshotRows');header(sr);sr.replaceChildren();const points=new Map([...(D.allSnapshots||[]),...D.reportingSnapshots().filter(s=>s.historical)].map(s=>[s.date,s]));for(const s of [...points.values()].filter(s=>!(D.hiddenSnapshotDates||[]).includes(s.date)).sort((a,b)=>b.date.localeCompare(a.date))){const tr=document.createElement('tr');for(const text of [s.date,s.historical?'历史家庭总额':s.complete?'盘点 / 流水推算':'资料不足',s.complete?money(D.total(s)):'资料不足'])tr.append(cell(text));tr.append(buttons([['修改',()=>snapshotEdit(s.date)],['删除',()=>M.check({action:'hide-snapshot',id:s.date})]]));sr.append(tr);}if(!sr.children.length){const tr=document.createElement('tr'),td=cell('暂无展示的资产历史，可从回收站恢复。');td.colSpan=4;tr.append(td);sr.append(tr);}
  // Balance / opening / transfer records live with the assets they affect.
  const journal=$('journalRows');header(journal);journal.replaceChildren();for(const r of (D.records||[]).filter(r=>r.type!=='income'&&r.order>0&&!r.portfolioValuation).slice().reverse()){const tr=document.createElement('tr');for(const text of [r.date,({transfer:'转账',opening:'初始余额',balance:'余额盘点'}[r.type]||r.type),(D.accounts.find(a=>a.id===r.account)?.name||r.account)+(r.target?' → '+(D.accounts.find(a=>a.id===r.target)?.name||r.target):''),nativeMoney(r.cents,r.currency||'CNY'),r.memo||r.source||''])tr.append(cell(text));const actions=[['修改',()=>M.edit('record',r.order,r)]];if(r.type!=='opening')actions.push(['删除',()=>M.check({action:'delete-record',id:r.order})]);tr.append(buttons(actions));journal.append(tr);}
  // The import history table also exposes actions directly on its original rows.
  const hr=$('historySavedRows');if(hr){header(hr);const history=(D.history||[]).slice().sort((a,b)=>b.date.localeCompare(a.date));for(let i=0;i<history.length;i++){const tr=hr.children[i],r=history.find(r=>r.key===tr?.dataset.historyKey)||history[i];if(!tr)continue;tr.querySelector('.row-actions')?.remove();tr.append(buttons([['修改',()=>M.edit('history',r.key,r)],['删除',()=>M.check({action:'delete-history',id:r.key})]]));}}
 }
 trashAt($('unifiedAccounts').querySelector('.panel-head'),'assets');trashAt($('assetHistory').querySelector('.panel-head'),'assets');trashAt($('journalRows').closest('article').querySelector('.panel-head'),'assets');trashAt($('expenseReportPanel').querySelector('.panel-head'),'income');trashAt($('monthlyExpensePanel').querySelector('.panel-head')||$('monthlyExpensePanel'),'income');trashAt($('details').querySelector('.panel-head'),'income');trashAt($('historySaved').querySelector('.history-saved-controls'),'all');
 const originalRender=render;render=function(){originalRender();draw();};document.addEventListener('family-ledger-ready',draw);document.addEventListener('family-session-ready',draw);document.addEventListener('family-app-ready',draw);window.addEventListener('hashchange',draw);window.FamilyInline={draw};if(D.live)draw();
})();
